import{_ as a,c as t,o as s,b0 as i}from"./chunks/framework.C5ev1SXp.js";const d="/scm-docs/assets/tftp-download-flow.dfoBzJHr.svg",u=JSON.parse('{"title":"LV045-WiFi-TFTP文件下载","description":null,"frontmatter":{"title":"LV045-WiFi-TFTP文件下载","date":"2026-10-31T06:53:21.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/esp8266/126d638f36e925e464c8cbd0","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-31T06:53:21.606Z","fulluuid":"464c8cbd05164a66ac5d4aa442f3c984","useduuid":"464c8cbd0"}},"headers":[],"relativePath":"sdoc/advanced-chapter/esp8266/126d638f36e925e464c8cbd0.md","filePath":"sdoc/30-进阶篇/02-ESP8266/LV045-WiFi-TFTP文件下载.md","lastUpdated":1793371011000}'),n={name:"sdoc/advanced-chapter/esp8266/126d638f36e925e464c8cbd0.md"};function l(o,e,p,c,r,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="lv045-wifi-tftp文件下载" tabindex="-1">LV045-WiFi-TFTP文件下载 <a class="header-anchor" href="#lv045-wifi-tftp文件下载" aria-label="Permalink to &quot;LV045-WiFi-TFTP文件下载&quot;">​</a></h1><p>本文接续 <a href="./LV040-WiFi连接与ping探测.html">LV040-WiFi连接与ping探测</a>，在 <code>flash-app</code> 工程里实现 <code>wifi tftp</code> 命令：MCU 通过 ESP8266 以 TFTP（RFC 1350）从局域网内的 Windows 服务器下载 <code>app.img</code>，整帧校验通过后暂存到 SPI Flash，为后续 bootloader 在线安装做准备。</p><h2 id="一、-at-指令-从联网到-tftp-通道" tabindex="-1">一、 AT 指令：从联网到 TFTP 通道 <a class="header-anchor" href="#一、-at-指令-从联网到-tftp-通道" aria-label="Permalink to &quot;一、 AT 指令：从联网到 TFTP 通道&quot;">​</a></h2><h3 id="_1-tftp-协议与-udp-前提" tabindex="-1">1. TFTP 协议与 UDP 前提 <a class="header-anchor" href="#_1-tftp-协议与-udp-前提" aria-label="Permalink to &quot;1. TFTP 协议与 UDP 前提&quot;">​</a></h3><p>TFTP 基于 UDP，服务器守在 UDP 69 端口等待请求，但<strong>回包改用临时端口发送</strong>——这个特性决定了后面所有指令参数的选择。协议本身只有 4 种包：</p><table tabindex="0"><thead><tr><th>操作码</th><th>包类型</th><th>方向</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>RRQ</td><td>客户端 → 服务器</td><td>读请求：文件名 + 模式串（<code>octet</code>）</td></tr><tr><td>3</td><td>DATA</td><td>服务器 → 客户端</td><td>数据块，固定 512 B，块号从 1 递增</td></tr><tr><td>4</td><td>ACK</td><td>客户端 → 服务器</td><td>确认收到的块号</td></tr><tr><td>5</td><td>ERROR</td><td>双向</td><td>出错（文件不存在、访问违规等）</td></tr></tbody></table><p>末块数据不足 512 B 即为传输结束，无需额外结束包。</p><h3 id="_2-多连接模式-at-cipmux" tabindex="-1">2. 多连接模式（AT+CIPMUX） <a class="header-anchor" href="#_2-多连接模式-at-cipmux" aria-label="Permalink to &quot;2. 多连接模式（AT+CIPMUX）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CIPMUX=1</span></span>
<span class="line"><span>OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>本方案固定使用多连接模式（MUX=1），原因有二：（1）只有 MUX=1 才能显式指定 UDP 本地端口，客户端端口稳定便于服务器回包与抓包对照；（2）透传排错时每条链路有 link id，日志更清晰。</p><p>代价是：<strong>MUX=1 之后，<code>AT+CIPSTART</code>、<code>AT+CIPSEND</code>、<code>AT+CIPCLOSE</code> 全部必须带 link id 前缀</strong>，漏掉就直接 ERROR——这是本链路最大的坑，实测复现见第三节。</p><h3 id="_3-建立-udp-链路-at-cipstart" tabindex="-1">3. 建立 UDP 链路（AT+CIPSTART） <a class="header-anchor" href="#_3-建立-udp-链路-at-cipstart" aria-label="Permalink to &quot;3. 建立 UDP 链路（AT+CIPSTART）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CIPSTART=0,&quot;UDP&quot;,&quot;192.168.10.103&quot;,69,8266,1</span></span>
<span class="line"><span>CONNECT</span></span>
<span class="line"><span>OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>六个参数依次是：link id（0）、类型（UDP）、远端 IP、远端端口（69 = TFTP）、本地端口（8266，任意未占用值）、mode。</p><p>关键是最后一个 mode 参数：</p><ul><li>mode = 0：对端固定，来自其它地址/端口的数据被丢弃；</li><li>mode = 1：<strong>变对端</strong>——收到新对端的数据后自动切换远端。</li></ul><p>TFTP 服务器的 DATA 包来自临时端口而非 69 端口，因此必须以 mode = 1 建链，否则第一块数据就收不到。</p><p>反例：MUX=1 下写成 <code>AT+CIPSTART=&quot;UDP&quot;,...</code>（不带 link id），5 参数与 4 参数两种形式实测都直接回 ERROR，且失败极快（9 ms）——秒失败本身就是&quot;指令格式被拒&quot;而非&quot;网络不通&quot;的信号。</p><h3 id="_4-数据收发-at-cipsend-与-ipd" tabindex="-1">4. 数据收发（AT+CIPSEND 与 +IPD） <a class="header-anchor" href="#_4-数据收发-at-cipsend-与-ipd" aria-label="Permalink to &quot;4. 数据收发（AT+CIPSEND 与 +IPD）&quot;">​</a></h3><p>发送方向：先声明长度，等提示符，再发原始字节：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CIPSEND=0,21</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>&gt;</span></span>
<span class="line"><span>(21 字节原始数据)</span></span>
<span class="line"><span>Recv 21 bytes</span></span>
<span class="line"><span>SEND OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><code>len</code> 是字节数，包内可以含 <code>0x00</code>；应答以 <code>&gt;</code> 为准，数据发出后模块回 <code>Recv &lt;n&gt; bytes</code> 与 <code>SEND OK</code>。</p><p>接收方向：模块主动上报 <code>+IPD</code> 帧：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+IPD,&lt;id&gt;,&lt;len&gt;:&lt;data&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>data</code> 是二进制，<strong>只能按 <code>&lt;len&gt;</code> 解析，绝不能用 <code>strstr</code> 定位内容</strong>——TFTP 包里充满 <code>0x00</code>。另一个时序细节：服务器的回包常在 <code>SEND OK</code> 之前、或与它合并成同一 UART 帧到达，在应用层等 <code>SEND OK</code> 会把 <code>+IPD</code> 一并吞掉，这是调试期实测踩到的坑（第三节 3）。</p><h3 id="_5-关闭链路-at-cipclose" tabindex="-1">5. 关闭链路（AT+CIPCLOSE） <a class="header-anchor" href="#_5-关闭链路-at-cipclose" aria-label="Permalink to &quot;5. 关闭链路（AT+CIPCLOSE）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CIPCLOSE=0</span></span>
<span class="line"><span>OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>传输完成或出错后都应关闭链路，避免残留 UDP 链路占用本地端口、干扰下次建链。</p><h2 id="二、-程序设计" tabindex="-1">二、 程序设计 <a class="header-anchor" href="#二、-程序设计" aria-label="Permalink to &quot;二、 程序设计&quot;">​</a></h2><h3 id="_1-总体流程" tabindex="-1">1. 总体流程 <a class="header-anchor" href="#_1-总体流程" aria-label="Permalink to &quot;1. 总体流程&quot;">​</a></h3><p>设计决策：<strong>先下载到外部 SRAM，整帧收完先校验、后落盘</strong>。外部 SRAM 有 1 MB（基址 <code>0x68000000</code>，FSMC Bank1 NOR/SRAM3），装得下 128 KB 的最大镜像；校验通过才写 Flash，坏数据永远不会污染存储区。</p><p><img src="`+d+`" alt="WiFi TFTP 下载链路"></p><p>流程分四步：</p><p>（1）建链：<code>AT+CIPMUX=1</code> → <code>AT+CIPSTART=0,&quot;UDP&quot;,&lt;host&gt;,69,8266,1</code>。</p><p>（2）传输：发 RRQ，循环收 DATA（写入 SRAM）回 ACK，直到某块数据不足 512 B；3 s 无帧重发上一包，最多 3 次。</p><p>（3）整帧校验：魔数 <code>IAPBIN02</code>、头部声明的载荷长度 N + 28 必须与实际收到的字节数完全相等、尾标 <code>IAPEOF02</code>、逐位 CRC32、目标地址白名单（<code>0x08020000</code> / <code>0x20007000</code>）。</p><p>（4）暂存：写入 SPI Flash <code>0x002000</code>（W25Q128 扇区 2），供后续 bootloader 校验安装。</p><p>镜像帧格式与 <code>tools/pack_iap.py</code> 打包工具严格对应（详见《LV040-image镜像文件打包原理与生成》）：</p><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>内容</th></tr></thead><tbody><tr><td>魔数</td><td>8 B</td><td><code>IAPBIN02</code></td></tr><tr><td>载荷长度</td><td>4 B</td><td>N，小端 uint32</td></tr><tr><td>CRC32</td><td>4 B</td><td>载荷的 zlib 参数 CRC32，小端</td></tr><tr><td>目标地址</td><td>4 B</td><td>小端 uint32</td></tr><tr><td>载荷</td><td>N B</td><td>app 本体</td></tr><tr><td>尾标</td><td>8 B</td><td><code>IAPEOF02</code></td></tr></tbody></table><p>整帧总长恒为 N + 28——这就是&quot;头部声明长度与实际字节数硬校验&quot;的依据。</p><h3 id="_2-代码结构与命令入口" tabindex="-1">2. 代码结构与命令入口 <a class="header-anchor" href="#_2-代码结构与命令入口" aria-label="Permalink to &quot;2. 代码结构与命令入口&quot;">​</a></h3><p><code>atk_mw8266d_net.h</code> 集中定义全部常量：</p><table tabindex="0"><thead><tr><th>宏</th><th>值</th><th>含义</th></tr></thead><tbody><tr><td><code>NET_TFTP_BLOCK_SIZE</code></td><td>512</td><td>RFC 1350 固定块大小</td></tr><tr><td><code>NET_TFTP_TIMEOUT_MS</code></td><td>3000</td><td>一块的等待上限，超时重发</td></tr><tr><td><code>NET_TFTP_MAX_RETRY</code></td><td>3</td><td>当前块最大重发次数</td></tr><tr><td><code>NET_IMG_PAYLOAD_MAX</code></td><td>128 KB</td><td>Flash APP 容器上限</td></tr><tr><td><code>NET_STAGE_ADDR</code></td><td><code>0x002000</code></td><td>SPI Flash 暂存区起始偏移</td></tr></tbody></table><p>UART 层配套两处改动：（1）新增 <code>atk_mw8266d_uart_send()</code>，阻塞式发送原始字节（≤ 2048，可含 <code>0x00</code>）——<code>printf</code> 按 <code>%s</code> 处理会遇 <code>0x00</code> 截断，无法发送 TFTP 包；（2）RX 缓冲从 256 扩到 1024，一条 <code>+IPD</code> 帧携带 512 B 数据加头部约 531 B，256 必然截断。</p><p>命令入口 <code>wifi tftp &lt;host&gt; &lt;file&gt;</code>：先经 <code>atk_mw8266d_get_ap_info()</code> 确认已联网，再依次执行下载 → 校验 → 暂存，每步失败即打印 <code>net_res_name()</code> 对应的错误名并返回。</p><h3 id="_3-tftp-会话实现" tabindex="-1">3. TFTP 会话实现 <a class="header-anchor" href="#_3-tftp-会话实现" aria-label="Permalink to &quot;3. TFTP 会话实现&quot;">​</a></h3><h4 id="_3-1-atk-mw8266d-net-tftp-get" tabindex="-1">3.1 atk_mw8266d_net_tftp_get() <a class="header-anchor" href="#_3-1-atk-mw8266d-net-tftp-get" aria-label="Permalink to &quot;3.1 atk_mw8266d_net_tftp_get()&quot;">​</a></h4><p>TFTP 下载主函数，该函数在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d_net.h</code> 文件中声明：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">net_res_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atk_mw8266d_net_tftp_get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">filename</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                                   uint8_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">dst</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> dst_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                                   uint32_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">img_len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>【<strong>函数作用</strong>】</p><p>建立 UDP 链路并发起 TFTP 读请求，把服务器返回的数据块逐块写入 <code>dst</code>，直到末块；无论成败都关闭链路后返回。内部按&quot;单缓冲帧&quot;处理 <code>+IPD</code>：一次 <code>+IPD</code> 恰好落在一条 UART 帧里，解析按长度取数据。</p><p>【<strong>参数含义</strong>】</p><ul><li><code>host</code>：TFTP 服务器 IP 字符串，不能为空</li><li><code>filename</code>：请求的文件名，最长 200 字节</li><li><code>dst</code>：下载缓冲区首地址（本方案传外部 SRAM 基址 <code>0x68000000</code>）</li><li><code>dst_size</code>：缓冲区容量，至少 516 B；超限立即返回 <code>NET_ERR_TOOLARGE</code></li><li><code>img_len</code>：实际下载字节数的落点，可为 NULL</li></ul><p>【<strong>返回值</strong>】</p><ul><li><code>NET_OK</code>：下载完成，<code>*img_len</code> 为实际字节数</li><li><code>NET_ERR_CONNECT</code>：建链或 RRQ 发送失败</li><li><code>NET_ERR_NOTFOUND</code>：服务器回 ERROR 1（文件不存在）</li><li><code>NET_ERR_TFTP</code>：其它协议层错误（链路被关、ACK 发送失败等）</li><li><code>NET_ERR_TIMEOUT</code>：3 s × 4 轮无任何回包</li><li><code>NET_ERR_TOOLARGE</code>：数据超出缓冲区容量</li></ul><p>重发策略与 TFTP 标准一致但更保守：还没收到块 1 时超时重发 RRQ；已经收过块 n 时超时重发对 n 的 ACK；收到块 n 的重复 DATA（服务器没收到上一个 ACK）就再 ACK 一次。乱序块直接丢弃，等服务器超时重传补齐。</p><h3 id="_4-镜像校验与暂存" tabindex="-1">4. 镜像校验与暂存 <a class="header-anchor" href="#_4-镜像校验与暂存" aria-label="Permalink to &quot;4. 镜像校验与暂存&quot;">​</a></h3><h4 id="_4-1-atk-mw8266d-net-img-verify" tabindex="-1">4.1 atk_mw8266d_net_img_verify() <a class="header-anchor" href="#_4-1-atk-mw8266d-net-img-verify" aria-label="Permalink to &quot;4.1 atk_mw8266d_net_img_verify()&quot;">​</a></h4><p>整帧校验，该函数在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d_net.h</code> 文件中声明：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">net_res_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atk_mw8266d_net_img_verify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint8_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">img</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> img_len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                                     uint32_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">payload_len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">target_addr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>【<strong>函数作用</strong>】</p><p>对 SRAM 里的整帧镜像做五道检查，全部通过才允许落盘。CRC32 用逐位实现（zlib 参数：<code>0xEDB88320</code> 反射，初值与终值异或 <code>0xFFFFFFFF</code>），与 <code>pack_iap.py</code> 的 <code>zlib.crc32</code> 严格一致。</p><p>【<strong>参数含义</strong>】</p><ul><li><code>img</code>：整帧镜像首地址</li><li><code>img_len</code>：实际收到的字节数</li><li><code>payload_len</code>：载荷长度落点，可为 NULL</li><li><code>target_addr</code>：目标地址落点，可为 NULL</li></ul><p>【<strong>返回值</strong>】</p><ul><li><code>NET_OK</code>：五道校验全部通过</li><li><code>NET_ERR_HDR</code>：任一校验失败（魔数、长度、尾标、CRC、目标地址白名单）</li></ul><p>五道校验里最关键的是长度硬校验：<code>img_len == 20 + N + 8</code> 必须精确成立，头里声明的长度与实际收到的字节数差一字节都算失败——这把&quot;下载被截断/多传&quot;这类问题挡在了落盘之前。</p><h4 id="_4-2-atk-mw8266d-net-stage" tabindex="-1">4.2 atk_mw8266d_net_stage() <a class="header-anchor" href="#_4-2-atk-mw8266d-net-stage" aria-label="Permalink to &quot;4.2 atk_mw8266d_net_stage()&quot;">​</a></h4><p>写入 SPI Flash 暂存区，该函数在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d_net.h</code> 文件中声明：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">net_res_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atk_mw8266d_net_stage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint8_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">img</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> img_len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>【<strong>函数作用</strong>】</p><p>把校验通过的整帧镜像写入 SPI Flash <code>NET_STAGE_ADDR</code>（<code>0x002000</code>）起的暂存区，走 <code>spiflash_write()</code>：跨扇区自动先擦除，写完自动回读比对。</p><p>【<strong>参数含义</strong>】</p><ul><li><code>img</code>：整帧镜像首地址</li><li><code>img_len</code>：整帧字节数</li></ul><p>【<strong>返回值</strong>】</p><ul><li><code>NET_OK</code>：写入且回读比对通过</li><li><code>NET_ERR_FLASH</code>：写入或比对失败</li></ul><h3 id="_5-实测结果" tabindex="-1">5. 实测结果 <a class="header-anchor" href="#_5-实测结果" aria-label="Permalink to &quot;5. 实测结果&quot;">​</a></h3><p>局域网实测（Windows Tftpd64 + 手机热点）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ESP8266] tftp get app.img from 192.168.10.103 ...</span></span>
<span class="line"><span>[ESP8266] recv 8192 bytes</span></span>
<span class="line"><span>[ESP8266] recv 16384 bytes</span></span>
<span class="line"><span>[ESP8266] recv 24576 bytes</span></span>
<span class="line"><span>[ESP8266] recv 32768 bytes</span></span>
<span class="line"><span>[ESP8266] downloaded 34472 bytes in 21350 ms</span></span>
<span class="line"><span>[ESP8266] verify ok: payload 34444 bytes, target 0x08020000</span></span>
<span class="line"><span>[ESP8266] staging to spi flash @ 0x00002000 ...</span></span>
<span class="line"><span>[ESP8266] staged 34472 bytes to flash @ 0x00002000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>34472 B 用时 21.3 s，约 1.6 KB/s。瓶颈不在 WiFi 而在 AT 指令流程：每 512 B 块都要走一遍 <code>AT+CIPSEND</code> 应答（<code>OK</code> → <code>&gt;</code> → <code>SEND OK</code>），115200 波特率下往返开销占绝对大头。对一次性的固件下载而言这个速度完全可接受，没有必要为它上透传模式。</p><h2 id="三、-常见问题排查" tabindex="-1">三、 常见问题排查 <a class="header-anchor" href="#三、-常见问题排查" aria-label="Permalink to &quot;三、 常见问题排查&quot;">​</a></h2><h3 id="_1-排查思路与工具" tabindex="-1">1. 排查思路与工具 <a class="header-anchor" href="#_1-排查思路与工具" aria-label="Permalink to &quot;1. 排查思路与工具&quot;">​</a></h3><p>（1）<strong>透传优先</strong>。MCU 侧逻辑复杂，先用 <code>at</code> 命令逐条验证 AT 指令层（<code>at AT+CIPMUX=1</code>、<code>at AT+CIPSTART=0,...</code>），指令层通了再看应用层。</p><p>（2）<strong>对照服务器日志</strong>。Tftpd64 的「Tftp 客户端」页每个请求一行：<code>总数</code> 列等于文件大小说明文件找到了；<code>字节</code> 列为 0 说明一块都没发出去或发出后没被 ACK；具体错误原因看「日志查看」页。</p><p>（3）<strong>分段定位</strong>。失败发生在哪一段决定了根因范围：秒失败是指令格式问题；请求到达但 0 字节是回包被吞；传一半超时是防火墙或丢包；下载成功但校验失败是镜像内容问题。</p><h3 id="_2-connect-failed-9-ms-即失败" tabindex="-1">2. connect failed（9 ms 即失败） <a class="header-anchor" href="#_2-connect-failed-9-ms-即失败" aria-label="Permalink to &quot;2. connect failed（9 ms 即失败）&quot;">​</a></h3><p>现象：<code>wifi tftp</code> 建链即报 <code>connect failed</code>，耗时仅几毫秒；透传下 <code>AT+CIPSTART=&quot;UDP&quot;,...</code> 回 ERROR，而 <code>AT+CIPMUX=1</code> 正常。</p><p>根因：MUX=1 模式下所有连接指令必须带 link id，<code>AT+CIPSTART</code> 漏掉 <code>0,</code> 前缀直接被指令层拒绝——失败快恰恰是格式错误的特征，真正的网络故障要等超时。</p><p>修复：<code>AT+CIPSTART=0,&quot;UDP&quot;,&lt;host&gt;,69,&lt;port&gt;,1</code>。</p><h3 id="_3-服务器收到请求但-0-字节-mcu-报-no-reply" tabindex="-1">3. 服务器收到请求但 0 字节，MCU 报 no reply <a class="header-anchor" href="#_3-服务器收到请求但-0-字节-mcu-报-no-reply" aria-label="Permalink to &quot;3. 服务器收到请求但 0 字节，MCU 报 no reply&quot;">​</a></h3><p>现象：Tftpd64 日志显示请求已到达、ERR、传输 0 字节；MCU 侧重试 4 轮后报 <code>no reply from server</code>。</p><p>根因：应用层在发出 RRQ 原始字节后还在等模块回 <code>SEND OK</code>，而服务器的 DATA/ERROR 帧就在这几毫秒内到达，被等待循环当作无关帧丢弃；之后每次超时重发 RRQ 都重复同样的竞态。Tftpd64 侧每次请求都重发 DATA 直到自己的超时，最终记 ERR、0 字节——两侧日志合起来才是完整证据链。</p><p>修复：（1）发完原始字节立即返回，不等 <code>SEND OK</code>，未送达由外层超时重发兜底；（2）<code>+IPD</code> 解析改为在帧内搜索 <code>+IPD,</code> 头，兼容它与 <code>SEND OK</code> 合并成一帧的情况。</p><h3 id="_4-第一块数据就报-image-too-large-for-buffer" tabindex="-1">4. 第一块数据就报 image too large for buffer <a class="header-anchor" href="#_4-第一块数据就报-image-too-large-for-buffer" aria-label="Permalink to &quot;4. 第一块数据就报 image too large for buffer&quot;">​</a></h3><p>现象：下载刚开始（第一块 512 B）就报 <code>image too large for buffer</code>。</p><p>根因：容量比较写成了 <code>(uint16_t)(dst_size - total)</code>，容量 131100 被截断成 28，512 B 的第一块必然超限。</p><p>修复：按 32 位比较，不缩窄类型。教训：容量/长度运算不要为了省事强转到窄类型。</p><h3 id="_5-超时时间比配置值长一倍" tabindex="-1">5. 超时时间比配置值长一倍 <a class="header-anchor" href="#_5-超时时间比配置值长一倍" aria-label="Permalink to &quot;5. 超时时间比配置值长一倍&quot;">​</a></h3><p>现象：配置的超时是 3 s × 4 轮 = 12 s，实测却接近 24 s。</p><p>根因：收包循环用 <code>quiet_ms++</code> 计数，每圈实际约 2 ms（<code>HAL_Delay(1)</code> 加处理开销），标称毫秒数被放大一倍。</p><p>修复：改用 <code>HAL_GetTick()</code> 差值计时。教训：轮询计数当毫秒用，前提是每圈严格 1 ms，否则一律用 tick。</p><h3 id="_6-现象速查表" tabindex="-1">6. 现象速查表 <a class="header-anchor" href="#_6-现象速查表" aria-label="Permalink to &quot;6. 现象速查表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>根因</th><th>修复</th></tr></thead><tbody><tr><td>建链秒失败（<code>connect failed</code>）</td><td>MUX=1 下 CIPSTART 缺 link id</td><td><code>AT+CIPSTART=0,&quot;UDP&quot;,...</code></td></tr><tr><td>服务器 ERR、0 字节，MCU no reply</td><td>等 <code>SEND OK</code> 吞掉 <code>+IPD</code></td><td>发完即返回 + 帧内搜索 IPD 头</td></tr><tr><td>收得到 IPD 但内容残缺</td><td>RX 缓冲小于 512 B + IPD 头</td><td>缓冲扩到 1024</td></tr><tr><td>建链正常但收不到 DATA</td><td>CIPSTART 少传 mode 或 mode=0</td><td>末参传 1（变对端）</td></tr><tr><td>PC 端抓不到回包方向流量</td><td>Windows 防火墙拦截 Tftpd64</td><td>放行 Tftpd64 或临时关闭防火墙</td></tr><tr><td>第一块就报 too large</td><td>容量比较被 uint16 截断</td><td>按 32 位比较</td></tr><tr><td>超时比配置值长一倍</td><td>轮询计数当毫秒用</td><td>改用 <code>HAL_GetTick()</code></td></tr></tbody></table><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,105)])])}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
